    name_koKR = "남쪽 산기슭 순환로", short_koKR = "남쪽 산기슭 순환로", zone_koKR = "불모의 땅", yields_koKR = "광석: 주석 광맥 65, 은 광맥 75", lap_koKR = "11~14분, 광석 채집지 2~4곳", note_koKR = "타우라조 야영지에서 남쪽으로 간 뒤, 가시덩굴 던전 입구 북쪽 산기슭을 따라 돌아옵니다. 호드 위험 중간. 남쪽에는 가시멧돼지와 천둥도마뱀이 많으니 지상으로 다니고 던전과 동굴은 건너뛰세요.",
