    name_frFR = "Coteaux du centre", short_frFR = "Coteaux du centre", zone_frFR = "Les Hinterlands", yields_frFR = "Minerai : Gisement de mithril 175, Gisement de vrai-argent 230", lap_frFR = "8–11 min, 2–6 filons", note_frFR = "Montez sur les hauteurs depuis le Village des Revantusk par la route est, puis rejoignez la boucle au milieu. Risque moyen pour la Horde ; Nid-de-l'Aigle à l’ouest appartient à l’Alliance, Seradane au nord abrite des élites de niveau 62 environ et Jintha'Alor au sud-est a aussi des élites ; restez en surface, l’entrée de la grotte aux champignons fantômes est facultative.",
    name_esES = "Laderas centrales", short_esES = "Laderas centrales", zone_esES = "Tierras del Interior", yields_esES = "Mineral: Depósito de mitril 175, Depósito de veraplata 230", lap_esES = "8–11 min, 2–6 nodos de mineral", note_esES = "Sube a las tierras altas desde el Poblado Sañadiente por el camino del este y únete al circuito por el medio. Riesgo medio para la Horda; Pico Nidal, al oeste, es de la Alianza; Seradane, al norte, tiene élites de nivel ~62 y Jintha'Alor, al sureste, también tiene élites; quédate en la superficie, la entrada de la cueva de champiñones fantasma es opcional.",
    name_esMX = "Laderas centrales", short_esMX = "Laderas centrales", zone_esMX = "Tierras del Interior", yields_esMX = "Mineral: Depósito de mitril 175, Depósito de veraplata 230", lap_esMX = "8–11 min, 2–6 nodos de mineral", note_esMX = "Sube a las tierras altas desde el Poblado Sañadiente por el camino del este y únete al circuito por el medio. Riesgo medio para la Horda; Pico Nidal, al oeste, es de la Alianza; Seradane, al norte, tiene élites de nivel ~62 y Jintha'Alor, al sureste, también tiene élites; quédate en la superficie, la entrada de la cueva de champiñones fantasma es opcional.",
    name_ruRU = "Центральные склоны", short_ruRU = "Центральные склоны", zone_ruRU = "Внутренние земли", yields_ruRU = "Руда: Мифриловые залежи 175, Залежи истинного серебра 230", lap_ruRU = "8–11 мин, точек руды: 2–6", note_ruRU = "Поднимитесь на высокогорье от деревни Сломанного Клыка по восточной дороге и присоединитесь к кругу в середине. Для Орды риск средний; Заоблачный Пик на западе принадлежит Альянсу, в Серадане на севере элитные противники ~62 уровня, в Джинта'Алоре на юго-востоке тоже элита; держитесь поверхности, вход в пещеру с призрачными грибами необязателен.",
    name_koKR = "중앙 언덕", short_koKR = "중앙 언덕", zone_koKR = "동부 내륙지", yields_koKR = "광석: 미스릴 광맥 175, 진은 광맥 230", lap_koKR = "8~11분, 광석 채집지 2~6곳", note_koKR = "레반터스크 마을에서 동쪽 길로 고지대에 오른 뒤 중간에서 순환로에 합류합니다. 호드 위험 중간. 서쪽 맹금의 봉우리는 얼라이언스 거점, 북쪽 세라데인에는 약 62레벨 정예, 남동쪽 진타알로에도 정예가 있습니다. 지상으로 다니고, 유령버섯 동굴 입구는 선택입니다.",
    name_ptBR = "Encostas centrais", short_ptBR = "Encostas centrais", zone_ptBR = "Terras Agrestes", yields_ptBR = "Minério: Depósito de Mithril 175, Depósito de Veraprata 230", lap_ptBR = "8–11 min, 2–6 pontos de minério", note_ptBR = "Suba ao planalto a partir da Aldeia Revatusco pela estrada leste e entre no circuito pelo meio. Risco médio para a Horda; o Ninho da Águia, a oeste, é da Aliança; Seradane, ao norte, tem elites de nível ~62 e Jintha'Alor, a sudeste, também tem elites; fique na superfície, a entrada da caverna do Cogumelo-fantasma é opcional.",
    pts = { { 74, 51 }, { 75, 55 }, { 69, 61 }, { 65, 60 }, { 61, 54 }, { 55, 50 }, { 50, 48 }, { 51, 54 }, { 52, 59 }, { 50, 63 }, { 48, 59 }, { 48, 55 }, { 46, 55 }, { 44, 58 }, { 43, 64 }, { 40, 64 }, { 37, 62 }, { 32, 63 }, { 31, 59 }, { 32, 53 }, { 34, 47 }, { 37, 48 }, { 40, 50 }, { 44, 47 }, { 49, 43 }, { 53, 42 }, { 57, 44 }, { 62, 44 }, { 65, 46 }, { 66, 50 }, { 69, 52 } } },
