    name_esES = "Circuito exterior de Kargath", short_esES = "Circuito exterior de Kargath", zone_esES = "Tierras Inhóspitas", yields_esES = "Mineral: Depósito de mitril 175, Depósito de veraplata 230", lap_esES = "8–12 min, 4–9 nodos de mineral", note_esES = "Sal de Kargath y rodea el borde exterior; en el norte vuelve a las laderas rodeando la excavación y la entrada de Uldaman. Riesgo medio para la Horda; en el Barranco Lethlor, al este, hay dragonantes, así que mantente en las laderas exteriores y cuidado con los elementales de roca al suroeste.",
