    name_ruRU = "Внешний круг у Каргата", short_ruRU = "Внешний круг у Каргата", zone_ruRU = "Бесплодные земли", yields_ruRU = "Руда: Мифриловые залежи 175, Залежи истинного серебра 230", lap_ruRU = "8–12 мин, точек руды: 4–9", note_ruRU = "Начните у Каргата и идите по внешнему краю; на севере вернитесь к предгорьям, обходя раскопки и вход в Ульдаман. Для Орды риск средний; в долине Летлор на востоке драконы, держитесь внешних склонов, на юго-западе опасайтесь каменных элементалей.",
    name_koKR = "카르가스 외곽 순환로", short_koKR = "카르가스 외곽 순환로", zone_koKR = "황야의 땅", yields_koKR = "광석: 미스릴 광맥 175, 진은 광맥 230", lap_koKR = "8~12분, 광석 채집지 4~9곳", note_koKR = "카르가스에서 출발해 바깥 가장자리를 돕니다. 북쪽에서는 울다만 발굴지와 입구를 돌아 산기슭으로 돌아옵니다. 호드 위험 중간. 동쪽 레슬로 협곡에는 용족이 있으니 바깥 비탈로 다니고, 남서쪽 바위 정령을 조심하세요.",
    name_ptBR = "Circuito externo de Karrath", short_ptBR = "Circuito externo de Karrath", zone_ptBR = "Ermos", yields_ptBR = "Minério: Depósito de Mithril 175, Depósito de Veraprata 230", lap_ptBR = "8–12 min, 4–9 pontos de minério", note_ptBR = "Comece em Karrath e contorne a borda externa; no norte, volte aos sopés contornando a escavação e a entrada de Uldaman. Risco médio para a Horda; a Ravina Lethlor, a leste, tem dracônicos, então fique nas encostas externas e cuidado com elementais de rocha a sudoeste.",
    pts = { { 7, 45 }, { 6, 39 }, { 11, 35 }, { 16, 35 }, { 20, 41 }, { 26, 42 }, { 32, 39 }, { 36, 35 }, { 39, 31 }, { 43, 28 }, { 48, 22 }, { 53, 23 }, { 57, 27 }, { 64, 29 }, { 70, 30 }, { 76, 33 }, { 79, 40 }, { 80, 47 }, { 79, 53 }, { 75, 59 }, { 72, 59 }, { 70, 55 }, { 68, 49 }, { 63, 48 }, { 61, 52 }, { 62, 58 }, { 62, 64 }, { 57, 69 }, { 50, 72 }, { 43, 73 }, { 37, 72 }, { 32, 72 }, { 26, 73 }, { 21, 76 }, { 15, 78 }, { 10, 76 }, { 9, 72 }, { 10, 66 }, { 11, 61 }, { 9, 55 }, { 7, 51 } } },
  { id = "M09", kind = "ore", min = 245, max = 274, map = 1449,
