    name_ruRU = "Круг по внешнему краю", short_ruRU = "Круг по внешнему краю", zone_ruRU = "Кратер Ун'Горо", yields_ruRU = "Руда: Залежи истинного серебра 230, Покрытые слизью залежи истинного серебра 230, Малая ториевая жила 245, Покрытая слизью ториевая жила 245", lap_ruRU = "17–22 мин, точек руды: 4–9", note_ruRU = "Выйдите на край от Укрытия Маршалла или пандуса из Танариса. Для Орды риск выше среднего; избегайте улья силитидов в Скользком овраге на юге, пещеры горилл в Пещере Лишайников на севере и Вулкана Огненного Венца в центре; по внешнему кругу тоже ходят дьявозавры.",
