    name_frFR = "Sud du Sépulcre", short_frFR = "Sud du Sépulcre", zone_frFR = "Forêt des Pins argentés", yields_frFR = "Herbes : Mage royal 50, Eglantine 70, Doulourante 100", lap_frFR = "8–11 min, 2–6 herbes", note_frFR = "Depuis le Sépulcre, suivez les bois extérieurs à l’ouest et au sud. Risque moyen pour la Horde ; évitez la porte de Bois-du-Bûcher et l’intérieur de Moulin-de-l'Ambre, attention aux patrouilles d’élite des Fils d’Arugal. Une entrée de mine se trouve vers (60,72) ; l’itinéraire reste en surface, et on ne sait pas encore si les points proches sont dans la grotte.",
    name_esES = "Sur de El Sepulcro", short_esES = "Sur de El Sepulcro", zone_esES = "Bosque de Argénteos", yields_esES = "Hierbas: Marregal 50, Brezospina 70, Hierba cardenal 100", lap_esES = "8–11 min, 2–6 nodos de hierbas", note_esES = "Desde El Sepulcro, sigue los bosques exteriores del oeste y del sur. Riesgo medio para la Horda; evita la puerta de la Aldea Piroleña y el interior de Molino Ámbar, y cuidado con las patrullas élite de Hijos de Arugal. Hay una entrada de mina hacia (60,72); la ruta va por la superficie y no se ha comprobado si los puntos cercanos están dentro de la cueva.",
    name_esMX = "Sur de El Sepulcro", short_esMX = "Sur de El Sepulcro", zone_esMX = "Bosque de Argénteos", yields_esMX = "Hierbas: Marregal 50, Brezospina 70, Hierba cardenal 100", lap_esMX = "8–11 min, 2–6 nodos de hierbas", note_esMX = "Desde El Sepulcro, sigue los bosques exteriores del oeste y del sur. Riesgo medio para la Horda; evita la puerta de la Aldea Piroleña y el interior de Molino Ámbar, y cuidado con las patrullas élite de Hijos de Arugal. Hay una entrada de mina hacia (60,72); la ruta va por la superficie y no se ha comprobado si los puntos cercanos están dentro de la cueva.",
