    pts = { { 44, 42 }, { 43, 48 }, { 45, 54 }, { 47, 59 }, { 50, 62 }, { 54, 63 }, { 58, 62 }, { 61, 64 }, { 60, 69 }, { 58, 73 }, { 54, 72 }, { 51, 68 }, { 48, 70 }, { 48, 74 }, { 45, 73 }, { 43, 68 }, { 42, 63 }, { 41, 58 }, { 40, 52 }, { 41, 46 } } },
