    name_koKR = "고숙련 약초 순환로", short_koKR = "고숙련 약초 순환로", zone_koKR = "악령의 숲", yields_koKR = "약초: 꿈풀 270, 은초롱이 280, 역병초 285", lap_koKR = "14~21분, 약초 채집지 6~19곳", note_koKR = "피멍울 초소나 남쪽 길에서 중간으로 합류합니다. 호드 위험 중간~높음. 중서부에서는 자에데나르와 어둠의 요새를 피하고, 북쪽에서는 마른가지 퍼볼그와 나무구렁 요새의 적대 평판을 조심하세요. 가파른 비탈을 곧장 가로지르지 마세요.",
