    pts = { { 61, 37 }, { 54, 35 }, { 55, 28 }, { 55, 23 }, { 51, 23 }, { 48, 19 }, { 47, 14 }, { 49, 10 }, { 53, 11 }, { 56, 15 }, { 61, 17 }, { 66, 18 }, { 66, 24 }, { 65, 29 }, { 65, 34 }, { 68, 36 }, { 66, 39 }, { 67, 46 }, { 66, 54 }, { 65, 61 }, { 62, 64 }, { 59, 64 }, { 57, 60 }, { 58, 54 }, { 59, 49 }, { 57, 45 }, { 52, 45 }, { 50, 43 }, { 51, 39 }, { 55, 36 } } },
