    name_ruRU = "К северу от Колючего Холма", short_ruRU = "К северу от Колючего Холма", zone_ruRU = "Дуротар", yields_ruRU = "Руда: Медная жила 1, Скудная медная жила 1 / Травы: Мироцвет 1, Сребролист 1, Землекорень 15, Магороза 50", lap_ruRU = "10–16 мин, точек руды: 3–7 / трав: 3–8", note_ruRU = "Начните с предгорий к северу от Колючего Холма и вернитесь северной дугой через леса и травянистые склоны. Для Орды риск низкий; избегайте крутых склонов перед Оргриммаром, пещеры Громового хребта и крепости Тирагард.",
