    name_ptBR = "Circuito do lado oeste", short_ptBR = "Circuito do lado oeste", zone_ptBR = "Ilha de Zefras", yields_ptBR = "Minério: Veio de Cobre 1 / Ervas: Botão-da-paz 1, Folha-prata 1, Raiz-telúrica 15", lap_ptBR = "10–15 min, 2–5 pontos de minério / 3–7 de ervas", note_ptBR = "Do povoado a oeste, siga para o interior pela crista oeste e depois pegue a trilha na margem oeste do Lago Cantéolo. Risco baixo a médio para a Horda; os recifes do oeste, os desníveis da margem e a curva em (46,54) não foram verificados, então fique na trilha.",
