    name_koKR = "크로스로드 북쪽", short_koKR = "크로스로드 북쪽", zone_koKR = "불모의 땅", yields_koKR = "광석: 주석 광맥 65, 은 광맥 75 / 약초: 마법초 50, 찔레가시 70, 생채기풀 100", lap_koKR = "13~19분, 광석 2~6곳 / 약초 3~10곳", note_koKR = "크로스로드에서 북쪽으로 마른 골짜기 가장자리까지 간 뒤 바위 비탈을 따라 돌아옵니다. 호드 위험 낮음~중간. 잊혀진 웅덩이 주변 켄타우로스 야영지와 북동쪽 진흙 늪은 돌아가고, 능선을 가로지르지 마세요.",
