    note = "由瑟伯切爾走西側及南段外林。部落中風險；避焚木村大門與安伯米爾鎮內，留意阿魯高之子菁英巡邏。礦洞口約 (60,72)，預設走地表；靠洞口的點是否在洞內（待實測）。",
    name_enUS = "Southern Loop", short_enUS = "Southern Loop", zone_enUS = "Silverpine Forest",
    yields_enUS = "Ore: Tin Vein 65, Silver Vein 75 / Herb: Mageroyal 50, Briarthorn 70, Bruiseweed 100",
    lap_enUS = "8–13 min, 2–5 ore / 2–6 herb nodes",
    note_enUS = "From the Sepulcher, follow the western and southern outer woods. Medium risk for Horde; avoid Pyrewood Village's gate and inner Ambermill, and watch for Son of Arugal elite patrols. A mine entrance is at about (60,72); the route stays on the surface, and whether nearby points are inside the cave is unverified.",
    name_zhCN = "南段", short_zhCN = "南段", zone_zhCN = "银松森林", yields_zhCN = "矿 锡矿 65、银矿 75／草 魔皇草 50、石南草 70、跌打草 100", lap_zhCN = "8–13 分钟、矿 2–5／草 2–6 个节点", note_zhCN = "由瑟伯切尔走西侧及南段外林。部落中风险；避开焚木村大门与安伯米尔镇内，留意阿鲁高之子精英巡逻。矿洞口约在 (60,72)，路线走地表；洞口附近的点是否在洞内尚未实测。",
