    name_deDE = "Äußere Runde um Kargath", short_deDE = "Äußere Runde um Kargath", zone_deDE = "Ödland", yields_deDE = "Erz: Goldvorkommen 155, Mithrilvorkommen 175 / Kräuter: Blassblatt 160, Golddorn 170, Khadgars Schnurrbart 185", lap_deDE = "9–14 Min., 4–9 Erzvorkommen / 2–7 Kräuter", note_deDE = "Start in Kargath und am äußeren Rand entlang; im Norden zurück zu den Ausläufern, um die Ausgrabungsstätte und den Eingang von Uldaman herum. Mittleres Risiko für die Horde; in der Lethlorklamm im Osten gibt es Drachkin, also an den äußeren Hängen bleiben, im Südwesten auf Felselementare achten.",
    name_frFR = "Boucle extérieure de Kargath", short_frFR = "Boucle extérieure de Kargath", zone_frFR = "Terres ingrates", yields_frFR = "Minerai : Filon d'or 155, Gisement de mithril 175 / Herbes : Pâlerette 160, Dorépine 170, Moustache de Khadgar 185", lap_frFR = "9–14 min, 4–9 filons / 2–7 herbes", note_frFR = "Partez de Kargath et suivez le bord extérieur ; au nord, revenez vers les contreforts en contournant le site de fouilles et l’entrée d’Uldaman. Risque moyen pour la Horde ; le Ravin de Lethlor à l’est abrite des draconiens, restez sur les pentes extérieures et méfiez-vous des élémentaires de roche au sud-ouest.",
    name_esES = "Circuito exterior de Kargath", short_esES = "Circuito exterior de Kargath", zone_esES = "Tierras Inhóspitas", yields_esES = "Mineral: Filón de oro 155, Depósito de mitril 175 / Hierbas: Pálida 160, Espina de oro 170, Vibrisa de Khadgar 185", lap_esES = "9–14 min, 4–9 nodos de mineral / 2–7 de hierbas", note_esES = "Sal de Kargath y rodea el borde exterior; en el norte vuelve a las laderas rodeando la excavación y la entrada de Uldaman. Riesgo medio para la Horda; en el Barranco Lethlor, al este, hay dragonantes, así que mantente en las laderas exteriores y cuidado con los elementales de roca al suroeste.",
    name_esMX = "Circuito exterior de Kargath", short_esMX = "Circuito exterior de Kargath", zone_esMX = "Tierras Inhóspitas", yields_esMX = "Mineral: Filón de oro 155, Depósito de mitril 175 / Hierbas: Pálida 160, Espina de oro 170, Mostacho de Khadgar 185", lap_esMX = "9–14 min, 4–9 nodos de mineral / 2–7 de hierbas", note_esMX = "Sal de Kargath y rodea el borde exterior; en el norte vuelve a las laderas rodeando la excavación y la entrada de Uldaman. Riesgo medio para la Horda; en el Barranco Lethlor, al este, hay dragonantes, así que mantente en las laderas exteriores y cuidado con los elementales de roca al suroeste.",
