    name_koKR = "카르가스 외곽 순환로", short_koKR = "카르가스 외곽 순환로", zone_koKR = "황야의 땅", yields_koKR = "광석: 금 광맥 155, 미스릴 광맥 175 / 약초: 미명초 160, 황금가시 170, 카드가의 수염 185", lap_koKR = "9~14분, 광석 4~9곳 / 약초 2~7곳", note_koKR = "카르가스에서 출발해 바깥 가장자리를 돕니다. 북쪽에서는 울다만 발굴지와 입구를 돌아 산기슭으로 돌아옵니다. 호드 위험 중간. 동쪽 레슬로 협곡에는 용족이 있으니 바깥 비탈로 다니고, 남서쪽 바위 정령을 조심하세요.",
