    name_ruRU = "Внешний круг у Круговзора", short_ruRU = "Внешний круг у Круговзора", zone_ruRU = "Зимние Ключи", yields_ruRU = "Руда: Малая ториевая жила 245, Богатая ториевая жила 275 / Травы: Горный серебряный шалфей 280, Ледяной зев 290, Черный лотос 300", lap_ruRU = "14–22 мин, точек руды: 3–7 / трав: 2–14", note_ruRU = "Идите на север от Круговзора к снежным полям и предгорьям у озера Кел'Терил. Орда может пополнить запасы в нейтральном городе; риск выше среднего, на севере много ледопардов; пропустите Теснину Ледяного Шепота, элиту Теснины Зловещего Шепота на юге и шахту у озера.",
